    "Kim heev!": ["Lub xov tooj no kim heev!","Lub xov tooj ntawd pheej yig.","This phone is really expensive! / That phone is cheap."],
    "Kuv mus kav khw.": ["Koj mus qhov twg?","Kuv mus kav khw.","Where are you going? / I'm going shopping."],
    "Koj mob qhov twg?": ["Koj mob qhov twg?","Kuv mob plab.","Where does it hurt? / My stomach hurts."],
