      {"t":"type","p":"Type: Do you speak English? (use puas)","a":["koj puas hais lus Askiv"],"hint":"koj · puas · hais lus Askiv · puas goes before the verb","x":["lub"],"why":"puas goes right before the verb; lus ends in the low tone letter -s."},
      {"t":"type","p":"Type: Where do you want to go?","a":["koj xav mus qhov twg"],"hint":"koj · xav · mus · qhov twg · the question word stays at the end","x":["muv"],"why":"The question word stays where the answer goes; mus has the low tone letter -s."},
      {"t":"type","p":"Type: Are you well? (use puas)","a":["koj puas nyob zoo"],"hint":"koj · puas · nyob · zoo","x":["nyom"],"why":"puas goes before the verb nyob, which ends in the high tone letter -b."}
